export interface AppCheckEnvironment {
  siteKey?: string;
  debug?: string;
  nodeEnv?: string;
  hostname?: string;
}

/** Shared by the browser bootstrap and production-build preflight. */
export function resolveAppCheckConfig(env: AppCheckEnvironment) {
  const siteKey = env.siteKey?.trim();
  const debug = env.debug?.trim();
  if (debug && debug !== 'false' && debug !== 'true') {
    throw new Error('App Check debug mode must be true or false, never a token.');
  }
  if (debug === 'true' && (env.nodeEnv !== 'development' || env.hostname !== 'localhost')) {
    throw new Error('App Check debug mode is restricted to development on localhost.');
  }
  if (!siteKey) {
    throw new Error(
      'Set REACT_APP_APP_CHECK_SITE_KEY to the registered reCAPTCHA v3 public site key.',
    );
  }
  return { siteKey, debug: debug === 'true' };
}
