import { devError } from './utils/developmentDiagnostics';
// firebase.js
import { initializeApp } from 'firebase/app';
import { getAuth } from 'firebase/auth';
import { getFirestore } from 'firebase/firestore';
import { initializeAppCheck, ReCaptchaV3Provider } from 'firebase/app-check';
import { resolveAppCheckConfig } from './utils/appCheckConfig';

const firebaseConfig = {
  apiKey: process.env.REACT_APP_FIREBASE_API_KEY,
  authDomain: process.env.REACT_APP_FIREBASE_AUTH_DOMAIN,
  projectId: process.env.REACT_APP_FIREBASE_PROJECT_ID,
  storageBucket: process.env.REACT_APP_FIREBASE_STORAGE_BUCKET,
  messagingSenderId: process.env.REACT_APP_FIREBASE_MESSAGING_SENDER_ID,
  appId: process.env.REACT_APP_FIREBASE_APP_ID,
};
// Initialize Firebase
const app = initializeApp(firebaseConfig);

// Initialize attestation before Auth/Firestore so the SDK can attach and refresh
// tokens for every Firebase auth entry point, including Google and email signup.
try {
  const config = resolveAppCheckConfig({
    siteKey: process.env.REACT_APP_APP_CHECK_SITE_KEY,
    debug: process.env.REACT_APP_APP_CHECK_DEBUG,
    nodeEnv: process.env.NODE_ENV,
    hostname: window.location.hostname,
  });
  // In local debug mode the SDK generates a browser-local token. Register it
  // privately; never place it in source, build variables, or production output.
  // Explicitly turn debug mode off in every other environment.
  (window as Window & { FIREBASE_APPCHECK_DEBUG_TOKEN?: boolean }).FIREBASE_APPCHECK_DEBUG_TOKEN =
    config.debug;
  initializeAppCheck(app, {
    provider: new ReCaptchaV3Provider(config.siteKey),
    isTokenAutoRefreshEnabled: true,
  });
} catch (error) {
  // Preserve public reading if local setup is incomplete. Authentication remains
  // blocked by server enforcement; production builds validate this configuration.
  devError('Firebase App Check initialization failed.');
}

// Initialize Firebase Auth
export const auth = getAuth(app);

// Initialize Firestore
export const db = getFirestore(app);
